import {sha,id} from './util.mjs';
export function sourceDocument(text){
 if(typeof text!=='string'||!text.trim())throw Error('EMPTY_SOURCE');
 const points=[...text],sha256=sha(Buffer.from(text,'utf8')),regions=[],nodes=[];let start=0;
 // Syntax-only line/sentence boundaries. The full original remains model input;
 // no semantic assertion is generated by segmentation or typed recognition.
 let fenced=false,section='DOCUMENT';
 for(let i=0;i<=points.length;i++)if(i===points.length||points[i]==='\n'){
  const end=i,line=points.slice(start,end).join('');
  if(line.trim()){
   if(/^\s*```/u.test(line))fenced=!fenced;
   const kind=fenced?'CODE':/^\s*#{1,6}\s/u.test(line)?'SECTION':/^\s*[-*+]\s|^\s*\d+[.)]\s/u.test(line)?'LIST_ITEM':/^\s*\|/u.test(line)?'TABLE_ROW':'PARAGRAPH';
   const nid=id(sha256,'structure',start,end);if(kind==='SECTION')section=nid;
   nodes.push({id:nid,kind,parent:kind==='SECTION'?'DOCUMENT':section,span:{start,end,quote:line}});
   regions.push({id:'c'+(regions.length+1),structure_id:nid,span:{start,end,quote:line}});
  }
  start=i+1;
 }
 const patterns=[['FILE',/[\p{L}\p{N}_./\\-]+\.(?:md|txt|csv|tsv|json|jsonl|ya?ml|toml|xml|log|py|js|mjs|ts|tsx|sql|pdf|docx|xlsx|parquet)\b/gu],['URI',/https?:\/\/[^\s<>()]+/gu],['VERSION',/\bv?\d+\.\d+(?:\.[\dx*]+)?(?:-[\w.]+)?/gu],['COMMIT',/\b[a-f\d]{7,40}\b/gu],['REFERENCE',/\b[A-Z][A-Z\d_-]*-\d[\w.-]*\b/gu],['NUMBER',/\b\d+(?:\.\d+)?%?/gu]],typed=[];
 for(const [type,re]of patterns)for(const m of text.matchAll(re)){const a=[...text.slice(0,m.index)].length,b=a+[...m[0]].length;typed.push({id:id(sha256,'literal',type,a,b),type,quote:m[0],span:{start:a,end:b},normalized:type==='NUMBER'?Number(m[0].replace('%','')):m[0]});}
 return {document_id:id(sha256,'source'),sha256,raw_text:text,offset_unit:'UNICODE_CODEPOINT',structure:{root:'DOCUMENT',nodes,declared_wp_headers:nodes.filter(n=>n.kind==='SECTION'&&/\bWP[-_ ]?\d+\b/iu.test(n.span.quote))},regions,typed_spans:typed};
}
